    'TRNC citizen' => ['TRNC-Staatsbürger', 'مواطن من جمهورية شمال قبرص التركية'],
    'Which property is this for you?' => ['Die wievielte Immobilie ist das für Sie?', 'ما ترتيب هذا العقار بالنسبة لك؟'],
    'First' => ['Erste', 'الأول'],
    'Seller' => ['Verkäufer', 'البائع'],
    'Developer / company (new build)' => ['Bauträger / Unternehmen (Neubau)', 'مطوّر / شركة (بناء جديد)'],
    'Private seller (resale)' => ['Privatverkäufer (Wiederverkauf)', 'بائع فرد (إعادة بيع)'],
    'Title deed transfer fee' => ['Grundbuchübertragungsgebühr', 'رسوم نقل سند الملكية'],
    'Based on the higher of the price and the Land Registry valuation.' => ['Bemessungsgrundlage ist der höhere Wert aus Kaufpreis und Schätzwert des Grundbuchamts.', 'الأساس الضريبي هو الأعلى بين سعر البيع والقيمة التقديرية التي يحددها السجل العقاري.'],
    'Reduced rate valid until %s (Official Gazette, Oct 2026).' => ['Ermäßigter Satz gültig bis %s (Amtsblatt, Okt. 2026).', 'النسبة المخفضة سارية حتى %s (الجريدة الرسمية، أكتوبر 2026).'],
    'VAT' => ['MwSt.', 'ضريبة القيمة المضافة'],
    'Only when buying from a developer/company. 10% for homes of 300 m² or more.' => ['Nur beim Kauf von einem Bauträger/Unternehmen. 10 % bei Wohnungen ab 300 m².', 'فقط عند الشراء من مطوّر عقاري/شركة. 10% للمساكن بمساحة 300 م² فأكثر.'],
    'Contract stamp duty' => ['Stempelsteuer auf den Vertrag', 'رسم الطابع على العقد'],
    'A penalty applies if not paid within 1 month of signing.' => ['Bei Zahlung nach mehr als 1 Monat ab Unterzeichnung fällt ein Zuschlag an.', 'تُفرض غرامة إذا لم يتم الدفع خلال شهر واحد من التوقيع.'],
    'Lawyer fee (+VAT)' => ['Anwaltsgebühr (zzgl. MwSt.)', 'أتعاب المحامي (+ ضريبة القيمة المضافة)'],
    'Typical market range; varies by lawyer.' => ['Marktübliche Spanne; je nach Anwalt unterschiedlich.', 'النطاق المعتاد في السوق؛ يختلف حسب المحامي.'],
    'Electricity transformer fee' => ['Transformatorgebühr (Strom)', 'رسوم محوّل الكهرباء'],
    'New developments; sometimes included in the price, ask the seller.' => ['Bei Neubauprojekten; manchmal im Preis enthalten, fragen Sie den Verkäufer.', 'في المشاريع الجديدة؛ تكون أحياناً مشمولة في السعر، اسأل البائع.'],
    'Water & electricity connection' => ['Wasser- und Stromanschluss', 'اشتراك المياه والكهرباء'],
    'Purchase permit application fee' => ['Antragsgebühr für die Kaufgenehmigung', 'رسوم طلب إذن الشراء'],
    'Council of Ministers permit for foreigners (approx.).' => ['Genehmigung des Ministerrats für Ausländer (ca.).', 'موافقة مجلس الوزراء للأجانب (مبلغ تقريبي).'],
    'Costs on top of the price' => ['Zusätzliche Kosten zum Kaufpreis', 'تكاليف إضافية على السعر'],
    'Approximate total' => ['Ungefähre Gesamtsumme', 'المجموع التقريبي'],
    'Approximate only; not legal or financial advice. Rates follow official texts as of %s and change often; the Land Registry and your lawyer confirm exact amounts. Agent commission and annual property tax are not included.' => ['Nur eine Schätzung; keine Rechts- oder Finanzberatung. Die Sätze beruhen auf den amtlichen Texten vom %s und ändern sich häufig; genaue Beträge bestätigen das Grundbuchamt und Ihr Anwalt. Maklerprovision und jährliche Grundsteuer sind nicht enthalten.', 'تقدير تقريبي فقط وليس استشارة قانونية أو مالية. تستند النسب إلى النصوص الرسمية بتاريخ %s وهي تتغير كثيراً؛ ويؤكد السجل العقاري ومحاميك المبالغ الدقيقة. عمولة الوسيط وضريبة العقار السنوية غير مشمولتين.'],
    'Request a video tour' => ['Videobesichtigung anfragen', 'طلب جولة بالفيديو'],
    'Video tour' => ['Videobesichtigung', 'جولة بالفيديو'],
    'Tour the property live over a video call from wherever you are. Pick a time; the advertiser will call to confirm.' => ['Besichtigen Sie die Immobilie live per Videoanruf – ganz gleich, wo Sie sind. Wählen Sie einen Termin; der Anbieter ruft Sie zur Bestätigung an.', 'تجوّل في العقار مباشرةً عبر مكالمة فيديو من أي مكان. اختر الوقت المناسب؛ وسيتصل بك صاحب الإعلان للتأكيد.'],
    'Phone / WhatsApp' => ['Telefon / WhatsApp', 'الهاتف / واتساب'],
    'Date' => ['Datum', 'التاريخ'],
    'Time' => ['Uhrzeit', 'الوقت'],
    'App' => ['App', 'التطبيق'],
    'Request video tour' => ['Videobesichtigung anfragen', 'اطلب جولة بالفيديو'],
    'Video tour request' => ['Anfrage für Videobesichtigung', 'طلب جولة بالفيديو'],
    'Get reminders on this device' => ['Erinnerungen auf diesem Gerät aktivieren', 'تفعيل التذكيرات على هذا الجهاز'],
    'Add client' => ['Kunden hinzufügen', 'إضافة عميل'],
    'Reminder (date & time)' => ['Erinnerung (Datum und Uhrzeit)', 'التذكير (التاريخ والوقت)'],
    'Notes' => ['Notizen', 'ملاحظات'],
    'Stage' => ['Status', 'الحالة'],
    'Add a stage, notes and a reminder for each client. Reminders arrive 1 day, 1 hour and 5 minutes before as phone notifications (or via Telegram).' => ['Geben Sie für jeden Kunden einen Status, Notizen und eine Erinnerung ein. Erinnerungen erreichen Sie 1 Tag, 1 Stunde und 5 Minuten vorher als Push-Benachrichtigung auf dem Handy (oder per Telegram).', 'أدخل لكل عميل حالة وملاحظات وتذكيراً. تصلك التذكيرات قبل يوم واحد وساعة واحدة و5 دقائق كإشعارات على هاتفك (أو عبر تيليغرام).'],
    'Smart search' => ['Intelligente Suche', 'البحث الذكي'],
    'Describe it: “2-bed rental near the sea in Kyrenia with a garden, under £1,000”' => ['Beschreiben Sie es: „2-Zimmer-Mietwohnung in Meeresnähe in Kyrenia mit Garten, unter 1.000 £“', 'صِف ما تبحث عنه: «شقة للإيجار بغرفتي نوم قرب البحر في كيرينيا مع حديقة، بأقل من 1,000 £»'],
    'Understanding your search…' => ['Ihre Suche wird verstanden…', 'جارٍ فهم بحثك…'],
    'Your sentence was turned into filters. Adjust them freely in the filter panel.' => ['Ihr Satz wurde in Filter umgewandelt. Sie können diese im Filterbereich beliebig anpassen.', 'تم تحويل جملتك إلى عوامل تصفية. يمكنك تعديلها كما تشاء من لوحة التصفية.'],
    'Area guides' => ['Gebietsführer', 'أدلة المناطق'],
    'Get to know North Cyprus neighbourhoods before you buy or rent: lifestyle, typical homes, who they suit and current listings.' => ['Lernen Sie die Gegenden Nordzyperns kennen, bevor Sie kaufen oder mieten: Lebensstil, typische Immobilien, für wen sie geeignet sind und aktuelle Angebote.', 'تعرّف على مناطق شمال قبرص قبل الشراء أو الإيجار: نمط الحياة، أنواع المنازل المعتادة، لمن تناسب، والإعلانات الحالية.'],
    'properties for sale in %s' => ['Immobilien zum Verkauf in %s', 'عقارات للبيع في %s'],
    'rentals in %s' => ['Mietangebote in %s', 'عقارات للإيجار في %s'],
    '%s median sale price per m²' => ['%s Median-Verkaufspreis pro m²', '%s متوسط سعر البيع للمتر المربع (الوسيط)'],
    '%s median monthly rent per m²' => ['%s Median-Monatsmiete pro m²', '%s متوسط الإيجار الشهري للمتر المربع (الوسيط)'],
    'Current listings in %s' => ['Aktuelle Angebote in %s', 'الإعلانات الحالية في %s'],
    'All sales in %s' => ['Alle Verkaufsangebote in %s', 'جميع إعلانات البيع في %s'],
    'All rentals in %s' => ['Alle Mietangebote in %s', 'جميع إعلانات الإيجار في %s'],
    'More areas in %s' => ['Weitere Gebiete in %s', 'مناطق أخرى في %s'],
    '%s area guide' => ['Gebietsführer %s', 'دليل منطقة %s'],
    'This guide is for general information. Figures are calculated automatically from current listings; visit the area before deciding.' => ['Dieser Führer dient der allgemeinen Information. Die Zahlen werden automatisch aus aktuellen Angeboten berechnet; besuchen Sie die Gegend, bevor Sie sich entscheiden.', 'هذا الدليل للمعلومات العامة فقط. تُحسب الأرقام تلقائيًا من الإعلانات الحالية؛ قم بزيارة المنطقة قبل اتخاذ قرارك.'],
    'Virtually staged (illustrative)' => ['Virtuell möbliert (Illustration)', 'مفروش افتراضيًا (للتوضيح)'],
    'Verified listing' => ['Verifiziertes Angebot', 'إعلان موثّق'],
    'The advertiser’s title deed or owner authorisation was checked by AdaCasa.' => ['Die Eigentumsurkunde oder die Eigentümervollmacht des Anbieters wurde von AdaCasa geprüft.', 'تم التحقق من سند الملكية أو تفويض المالك الخاص بالمعلن من قِبل AdaCasa.'],
    'Home seekers' => ['Wohnungssuchende', 'الباحثون عن منزل'],
    'Do I pay %site% to buy or rent a home?' => ['Muss ich bei %site% für den Kauf oder die Miete einer Immobilie bezahlen?', 'هل أدفع رسومًا إلى %site% لشراء منزل أو استئجاره؟'],
    'No. Browsing, saving favourites and messaging advertisers are free. %site% is not a party to the sale or rental; you deal directly with the advertiser (agency, developer, agent or owner). Ask them whether a commission applies.' => ['Nein. Stöbern, Favoriten speichern und Anbieter kontaktieren sind kostenlos. %site% ist nicht Partei des Kauf- oder Mietvertrags; Sie verhandeln direkt mit dem Anbieter (Makler, Bauträger, Berater oder Eigentümer). Fragen Sie nach, ob eine Provision anfällt.', 'لا. التصفح وحفظ المفضلة ومراسلة المعلنين مجاني. %site% ليس طرفًا في عملية البيع أو الإيجار؛ فأنت تتعامل مباشرة مع المعلن (وكالة عقارية أو مطوّر أو وسيط أو مالك). اسأله إن كانت هناك عمولة.'],
    'What do the title deed types mean?' => ['Was bedeuten die Eigentumsurkunden-Arten?', 'ما معنى أنواع سندات الملكية؟'],
    'Every sale listing in North Cyprus shows the title deed type: Turkish title, exchange (eşdeğer), allocation (tahsis), Evkaf (foundation), off-plan (contract) or other. A short explanation of each is in the “Title deed” section of the listing. The deed type directly affects your risk; always have the deed and documents checked by an independent lawyer before buying.' => ['Jede Verkaufsanzeige in Nordzypern nennt die Art der Eigentumsurkunde: türkischer Titel (Türk koçanı), Tausch (eşdeğer), Zuteilung (tahsis), Evkaf (Stiftung), Kauf vom Plan (Vertrag) oder Sonstiges. Eine kurze Erklärung zu jeder Art finden Sie im Abschnitt „Eigentumsurkunde“ der Anzeige. Die Urkundenart beeinflusst Ihr Risiko unmittelbar; lassen Sie Urkunde und Unterlagen vor dem Kauf stets von einem unabhängigen Rechtsanwalt prüfen.', 'يعرض كل إعلان بيع في شمال قبرص نوع سند الملكية: السند التركي (Türk koçanı)، أو المبادلة (eşdeğer)، أو التخصيص (tahsis)، أو الوقف (Evkaf)، أو البيع على الخارطة (بعقد)، أو غير ذلك. يوجد شرح موجز لكل نوع في قسم «سند الملكية» ضمن الإعلان. يؤثر نوع السند مباشرةً في مستوى المخاطرة لديك؛ لذا اطلب دائمًا من محامٍ مستقل فحص السند والمستندات قبل الشراء.'],
    'Can foreigners buy property in North Cyprus?' => ['Können Ausländer in Nordzypern Immobilien kaufen?', 'هل يمكن للأجانب شراء عقارات في شمال قبرص؟'],
    'Yes. Foreign buyers need permission from the Council of Ministers before the title can be transferred into their name. Conditions such as land size, timings and taxes change from time to time. Check the current rules with a lawyer before signing; your lawyer can also handle the permission application and register the contract at the Land Registry.' => ['Ja. Ausländische Käufer benötigen die Genehmigung des Ministerrats, bevor die Eigentumsurkunde auf ihren Namen umgeschrieben werden kann. Bedingungen wie Grundstücksgröße, Fristen und Steuern ändern sich von Zeit zu Zeit. Lassen Sie sich vor der Unterschrift von einem Anwalt über die aktuellen Regeln beraten; Ihr Anwalt kann auch den Genehmigungsantrag stellen und den Vertrag beim Grundbuchamt registrieren.', 'نعم. يحتاج المشترون الأجانب إلى إذن من مجلس الوزراء قبل نقل سند الملكية إلى أسمائهم. تتغير شروط مثل مساحة الأرض والمدد والضرائب من وقت لآخر. استشر محاميًا بشأن القواعد الحالية قبل التوقيع؛ ويمكن لمحاميك أيضًا متابعة طلب الإذن وتسجيل العقد لدى دائرة السجل العقاري.'],
    'Why are prices shown in different currencies?' => ['Warum werden Preise in verschiedenen Währungen angezeigt?', 'لماذا تظهر الأسعار بعملات مختلفة؟'],
    'Advertisers enter the price in their own currency (usually sterling). Use the currency selector at the top to see all prices in £, €, $ or ₺; the amount in brackets is a second currency. Rates are updated automatically (central bank and, when enabled, intraday market rates); the source and time are shown in the currency converter. The binding price is always the advertiser’s original amount.' => ['Inserenten geben den Preis in ihrer eigenen Währung ein (meist Pfund Sterling). Mit der Währungsauswahl oben können Sie alle Preise in £, €, $ oder ₺ anzeigen; der Betrag in Klammern ist eine zweite Währung. Die Kurse werden automatisch aktualisiert (Zentralbank und, falls aktiviert, Intraday-Marktkurse); Quelle und Uhrzeit stehen im Währungsrechner. Maßgeblich ist stets der ursprüngliche Betrag des Inserenten.', 'يُدخل المعلنون السعر بعملتهم الخاصة (غالبًا الجنيه الإسترليني). استخدم محدد العملة في الأعلى لعرض جميع الأسعار بالجنيه £ أو اليورو € أو الدولار $ أو الليرة ₺؛ والمبلغ بين القوسين هو عملة ثانية. تُحدَّث الأسعار تلقائيًا (من البنك المركزي، ومن أسعار السوق خلال اليوم عند تفعيلها)، ويظهر المصدر والوقت في محوّل العملات. السعر المعتمد هو دائمًا المبلغ الأصلي الذي أدخله المعلن.'],
    'How do I contact the advertiser?' => ['Wie kontaktiere ich den Inserenten?', 'كيف أتواصل مع المعلن؟'],
    'Each listing has “Show phone”, WhatsApp and a “Send a message” form. Messages from the form reach the advertiser instantly by email and Telegram. Mentioning the reference number (e.g. #10023) speeds things up.' => ['Jedes Inserat bietet „Telefon anzeigen“, WhatsApp und ein Formular „Nachricht senden“. Nachrichten aus dem Formular erreichen den Inserenten sofort per E-Mail und Telegram. Die Angabe der Referenznummer (z. B. #10023) beschleunigt die Bearbeitung.', 'يتضمن كل إعلان خيار «إظهار الهاتف» وواتساب ونموذج «إرسال رسالة». تصل الرسائل المرسلة عبر النموذج إلى المعلن فورًا عبر البريد الإلكتروني وتيليجرام. ذكر رقم الإعلان (مثل #10023) في رسالتك يسرّع الرد.'],
    'Is the listing still available?' => ['Ist das Inserat noch aktuell?', 'هل الإعلان ما زال متاحًا؟'],
    'Advertisers mark sold or let properties as “Sold” or “Inactive”. If you still find an unavailable property, use “Report this listing” on the page and our team will check it.' => ['Inserenten markieren verkaufte oder vermietete Objekte als „Verkauft“ oder „Inaktiv“. Finden Sie dennoch ein nicht mehr verfügbares Objekt, nutzen Sie auf der Seite „Dieses Inserat melden“ – unser Team prüft es.', 'يقوم المعلنون بتحديد العقارات المباعة أو المؤجرة على أنها «مباع» أو «غير نشط». إذا وجدت مع ذلك عقارًا غير متاح، فاستخدم «الإبلاغ عن هذا الإعلان» في الصفحة وسيقوم فريقنا بمراجعته.'],
    'What do you do about duplicate or misleading listings?' => ['Was unternehmen Sie gegen doppelte oder irreführende Inserate?', 'ماذا تفعلون بشأن الإعلانات المكررة أو المضللة؟'],
    'Every photo gets a visual fingerprint and every description a checksum, compared automatically. If the same photo or text is already live elsewhere, the advertiser is warned and our team is notified. Visitor reports are reviewed too. Please report anyone asking for a deposit before showing the property; never pay before viewing and before your lawyer has checked.' => ['Jedes Foto erhält einen visuellen Fingerabdruck und jede Beschreibung eine Prüfsumme, die automatisch verglichen werden. Ist dasselbe Foto oder derselbe Text bereits anderswo online, wird der Inserent gewarnt und unser Team benachrichtigt. Auch Meldungen von Besuchern werden geprüft. Bitte melden Sie jeden, der vor der Besichtigung eine Anzahlung verlangt; zahlen Sie nie vor der Besichtigung und bevor Ihr Anwalt alles geprüft hat.', 'يحصل كل صورة على بصمة بصرية وكل وصف على رمز تحقق، وتتم مقارنتها تلقائيًا. إذا كانت الصورة أو النص نفسه منشورًا بالفعل في مكان آخر، يتم تحذير المعلن وإشعار فريقنا. كما تتم مراجعة بلاغات الزوار. يرجى الإبلاغ عن أي شخص يطلب دفعة مقدمة قبل عرض العقار؛ ولا تدفع أبدًا قبل المعاينة وقبل أن يتحقق محاميك.'],
    'What is a 360° tour?' => ['Was ist eine 360°-Tour?', 'ما هي الجولة بزاوية 360°؟'],
    'Some listings include 360° photos of each room. Press “Start 360° tour” and look around by dragging or turning your phone, switching between rooms. Tick “🌐 360°” in the search to see only these listings.' => ['Einige Inserate enthalten 360°-Fotos jedes Raums. Tippen Sie auf „360°-Tour starten“ und sehen Sie sich per Ziehen oder durch Drehen Ihres Telefons um; zwischen den Räumen können Sie wechseln. Aktivieren Sie in der Suche „🌐 360°“, um nur diese Inserate zu sehen.', 'تتضمن بعض الإعلانات صور 360° لكل غرفة. اضغط على «بدء جولة 360°» وتطلّع حولك بالسحب أو بتدوير هاتفك، مع التنقل بين الغرف. فعّل خيار «🌐 360°» في البحث لعرض هذه الإعلانات فقط.'],
    'How is the price index calculated?' => ['Wie wird der Preisindex berechnet?', 'كيف يتم احتساب مؤشر الأسعار؟'],
    'The price index is the monthly median asking price per m² of live residential listings, by town. It reflects asking prices, not completed sales, and shows the market direction. The “x% below/above the area median” note on listings uses the same figure.' => ['Der Preisindex ist der monatliche Median der Angebotspreise pro m² aller aktiven Wohnimmobilienanzeigen, aufgeschlüsselt nach Stadt. Er bildet Angebotspreise ab, keine abgeschlossenen Verkäufe, und zeigt die Marktrichtung. Der Hinweis „x % unter/über dem Gebietsmedian“ bei den Anzeigen basiert auf demselben Wert.', 'مؤشر الأسعار هو الوسيط الشهري لأسعار الطلب لكل م² للإعلانات السكنية المنشورة حالياً، بحسب المدينة. وهو يعكس أسعار الطلب وليس عمليات البيع المنجزة، ويُظهر اتجاه السوق. وتستخدم ملاحظة «أقل/أعلى بنسبة x% من وسيط المنطقة» في الإعلانات الرقم نفسه.'],
    'Agents and owners' => ['Makler und Eigentümer', 'الوكلاء والمالكون'],
    'Is listing a property free?' => ['Ist das Inserieren einer Immobilie kostenlos?', 'هل نشر الإعلان مجاني؟'],
    'No, listing is free and will stay free. Only the optional automation packages are paid: posting your listings to 101evler and hangiev, and sharing them automatically on your Facebook / Instagram accounts.' => ['Nein, das Inserieren ist kostenlos und bleibt es auch. Kostenpflichtig sind nur die optionalen Automatisierungspakete: die Übertragung Ihrer Inserate zu 101evler und hangiev sowie die automatische Veröffentlichung auf Ihren Facebook-/Instagram-Konten.', ''],
    'How do I sign up and how long does it take?' => ['Wie registriere ich mich und wie lange dauert das?', 'كيف أسجّل وكم يستغرق ذلك؟'],
    'Choose your account type under “Register”: agency, developer, independent agent or owner. After confirming your email you can use your panel. Agency and developer accounts are approved once, after which listings go live instantly. Listings by independent agents and owners are published after a short check.' => ['Wählen Sie unter „Registrieren“ Ihren Kontotyp: Immobilienbüro, Bauträger, selbstständiger Makler oder Eigentümer. Nach der Bestätigung Ihrer E-Mail-Adresse können Sie Ihr Panel nutzen. Konten von Büros und Bauträgern werden einmalig freigegeben, danach gehen Anzeigen sofort online. Anzeigen von selbstständigen Maklern und Eigentümern werden nach einer kurzen Prüfung veröffentlicht.', 'اختر نوع حسابك من «تسجيل»: مكتب عقارات، شركة تطوير، وسيط مستقل أو مالك. بعد تأكيد بريدك الإلكتروني يمكنك استخدام لوحتك. تتم الموافقة على حسابات المكاتب وشركات التطوير مرة واحدة، وبعدها تُنشر الإعلانات فوراً. أما إعلانات الوسطاء المستقلين والمالكين فتُنشر بعد مراجعة قصيرة.'],
    'How do I add a listing?' => ['Wie füge ich eine Anzeige hinzu?', 'كيف أضيف إعلاناً؟'],
    'Two ways. My panel → “Add listing”: a step-by-step form with map location, drag-and-drop photos and 360° photos. Or Telegram: send the photos and your notes to our bot and press “Prepare listing”; AI extracts the details and writes the Turkish, English and Russian text, you check the preview and press “Publish”.' => ['Es gibt zwei Wege. Mein Panel → „Anzeige hinzufügen“: ein Schritt-für-Schritt-Formular mit Kartenstandort, Drag-and-drop-Fotos und 360°-Fotos. Oder Telegram: Senden Sie die Fotos und Ihre Notizen an unseren Bot und tippen Sie auf „Anzeige vorbereiten“; die KI extrahiert die Angaben und verfasst den türkischen, englischen und russischen Text, Sie prüfen die Vorschau und tippen auf „Veröffentlichen“.', 'هناك طريقتان. لوحتي ← «إضافة إعلان»: نموذج خطوة بخطوة مع تحديد الموقع على الخريطة، وصور بالسحب والإفلات، وصور 360°. أو تيليجرام: أرسل الصور وملاحظاتك إلى البوت الخاص بنا واضغط «تجهيز الإعلان»؛ يستخرج الذكاء الاصطناعي التفاصيل ويكتب النص بالتركية والإنجليزية والروسية، وتراجع أنت المعاينة وتضغط «نشر».'],
    'Is my listing published in three languages?' => ['Wird meine Anzeige in drei Sprachen veröffentlicht?', 'هل يُنشر إعلاني بثلاث لغات؟'],
    'Yes. The site runs in Turkish, English and Russian. For listings sent via Telegram, titles and descriptions are written automatically in all three. In the panel you can edit each language; if one is empty, the Turkish text is shown.' => ['Ja. Die Website ist auf Türkisch, Englisch und Russisch verfügbar. Bei Inseraten, die über Telegram eingehen, werden Titel und Beschreibung automatisch in allen drei Sprachen verfasst. Im Panel können Sie jede Sprache bearbeiten; ist eine leer, wird der türkische Text angezeigt.', 'نعم. يعمل الموقع بالتركية والإنجليزية والروسية. في الإعلانات الواردة عبر تيليغرام يتم كتابة العنوان والوصف تلقائيًا باللغات الثلاث. ويمكنك تعديل كل لغة من لوحة التحكم؛ وإذا كانت إحداها فارغة يُعرض النص التركي.'],
    'How many photos can I add? Can I add 360°?' => ['Wie viele Fotos kann ich hinzufügen? Kann ich 360°-Fotos hinzufügen?', 'كم صورة يمكنني إضافتها؟ وهل يمكنني إضافة صور 360°؟'],
    'Up to 30 photos and 15 360° photos per listing. Photos are resized and converted automatically for speed. 360° photos must be 2:1 (360° camera or the phone’s “Photo Sphere” mode). Send 360° photos to Telegram as a “File”.' => ['Bis zu 30 Fotos und 15 360°-Fotos pro Inserat. Die Fotos werden für schnelles Laden automatisch verkleinert und konvertiert. 360°-Fotos müssen im Format 2:1 vorliegen (360°-Kamera oder der Modus „Photo Sphere“ des Smartphones). Senden Sie 360°-Fotos über Telegram als „Datei“.', 'يمكنك إضافة حتى 30 صورة و15 صورة 360° لكل إعلان. يتم تصغير الصور وتحويلها تلقائياً لسرعة التحميل. يجب أن تكون صور 360° بنسبة 2:1 (كاميرا 360° أو وضع «Photo Sphere» في الهاتف). أرسل صور 360° عبر Telegram بصيغة «ملف».'],
    'Why did I get “A similar listing is already live”?' => ['Warum habe ich die Meldung „Ein ähnliches Inserat ist bereits online“ erhalten?', 'لماذا ظهرت لي رسالة «يوجد إعلان مشابه منشور بالفعل»؟'],
    'One of your photos or your description is identical to another live listing. If you listed the same property twice, update the older one instead. Photos and text must be your own; copied content is reported to our team.' => ['Eines Ihrer Fotos oder Ihre Beschreibung ist identisch mit einem anderen veröffentlichten Inserat. Wenn Sie dieselbe Immobilie zweimal eingestellt haben, aktualisieren Sie stattdessen das ältere Inserat. Fotos und Text müssen von Ihnen stammen; kopierte Inhalte werden unserem Team gemeldet.', 'إحدى صورك أو وصفك مطابق تماماً لإعلان آخر منشور. إذا نشرت العقار نفسه مرتين، فحدّث الإعلان الأقدم بدلاً من ذلك. يجب أن تكون الصور والنصوص من إنتاجك؛ ويتم إبلاغ فريقنا بالمحتوى المنسوخ.'],
    'What happens to my listings if I leave an agency?' => ['Was geschieht mit meinen Inseraten, wenn ich eine Agentur verlasse?', 'ماذا يحدث لإعلاناتي إذا غادرت المكتب العقاري؟'],
    'Listings you create while in an agency’s team belong to that agency’s portfolio. If you leave, are removed or move to another agency, they are moved to draft, taken offline and locked. At the agency’s request they are transferred to the person the agency names; if the agency does not want them, they are unlocked and stay with you. Listings you created before joining are always yours.' => ['Inserate, die Sie als Mitglied des Teams einer Agentur erstellen, gehören zum Portfolio dieser Agentur. Wenn Sie das Team verlassen, entfernt werden oder zu einer anderen Agentur wechseln, werden sie in den Entwurfsstatus versetzt, offline genommen und gesperrt. Auf Antrag der Agentur werden sie an die von ihr benannte Person übertragen; wenn die Agentur sie nicht möchte, wird die Sperre aufgehoben und sie bleiben bei Ihnen. Inserate, die Sie vor dem Beitritt erstellt haben, gehören immer Ihnen.', 'الإعلانات التي تنشئها أثناء عضويتك في فريق مكتب عقاري تعود إلى محفظة ذلك المكتب. وإذا غادرت الفريق أو تمت إزالتك أو انتقلت إلى مكتب آخر، فسيتم تحويلها إلى مسودة وإيقاف نشرها وقفلها. وبناءً على طلب المكتب تُنقل إلى الشخص الذي يحدده؛ وإذا لم يرغب المكتب بها، يُرفع القفل وتبقى لديك. أما الإعلانات التي أنشأتها قبل الانضمام فهي دائماً ملكك.'],
    'Where do I see enquiries?' => ['Wo sehe ich Anfragen (Kundennachrichten)?', 'أين أرى الطلبات (رسائل العملاء)؟'],
    'Every message from your listing pages arrives instantly by email and, if connected, Telegram. All are listed in My panel → “Enquiries”, where you can mark them read, done or spam.' => ['Jede Nachricht von Ihren Inseratsseiten erreicht Sie sofort per E-Mail und, falls verbunden, per Telegram. Alle werden unter Mein Panel → „Anfragen“ aufgelistet, wo Sie sie als gelesen, erledigt oder als Spam markieren können.', 'تصلك كل رسالة من صفحات إعلاناتك فورًا عبر البريد الإلكتروني، وعبر تيليغرام إن كان مرتبطًا. وتُعرض جميعها في لوحتي ← «الطلبات»، حيث يمكنك تحديدها كمقروءة أو منجزة أو كرسائل مزعجة.'],
    'Can my agency have its own page?' => ['Kann mein Büro eine eigene Seite haben?', 'هل يمكن أن يكون لمكتبي صفحة خاصة به؟'],
    'Yes. Every member has a showcase page with logo, contact details, social accounts and all listings (e.g. /en/agent/your-agency/). It can also run on its own subdomain (youragency.domain.com). You are listed in the agencies directory too.' => ['Ja. Jedes Mitglied hat eine Präsentationsseite mit Logo, Kontaktdaten, Social-Media-Konten und allen Inseraten (z. B. /en/agent/your-agency/). Sie kann auch unter einer eigenen Subdomain laufen (youragency.domain.com). Außerdem sind Sie im Verzeichnis der Büros gelistet.', 'نعم. لكل عضو صفحة عرض تضم الشعار وبيانات التواصل وحسابات التواصل الاجتماعي وجميع الإعلانات (مثال: /en/agent/your-agency/). ويمكن أيضًا تشغيلها على نطاق فرعي خاص بك (youragency.domain.com). كما يتم إدراجك في دليل المكاتب العقارية.'],
    'Packages and automation' => ['Pakete und Automatisierung', 'الباقات والأتمتة'],
    'What do the automation packages do?' => ['Wozu dienen die Automatisierungspakete?', 'ما فائدة باقات الأتمتة؟'],
    'You enter your listing once; with a package, the “Listing Transfer” browser extension fills it into 101evler and hangiev, and it is shared automatically on your Facebook Page and Instagram business account. No more typing the same listing on three sites.' => ['Sie geben Ihr Inserat nur einmal ein; mit einem Paket wird es über die Browser-Erweiterung „Inserat-Übertragung“ in die Formulare von 101evler und hangiev eingetragen und automatisch auf Ihrer Facebook-Seite und Ihrem Instagram-Business-Konto geteilt. Sie müssen dasselbe Inserat nicht mehr auf drei Websites tippen.', ''],
    'How does posting to 101evler and hangiev work? Is my account at risk?' => ['Wie funktioniert die Übertragung zu 101evler und hangiev? Ist mein Konto gefährdet?', ''],
    'The extension runs on your own computer with your own account; it fills the form and attaches the photos. You always press “Publish” yourself and solve any captcha; if an SMS code is needed it is requested via Telegram. It does not behave like a bot, so it is no different from posting manually.' => ['Die Erweiterung läuft auf Ihrem eigenen Computer mit Ihrem eigenen Konto; sie füllt das Formular aus und fügt die Fotos hinzu. Auf „Veröffentlichen“ klicken immer Sie selbst, und ein Captcha lösen Sie ebenfalls selbst; wird ein SMS-Code benötigt, wird er per Telegram abgefragt. Sie verhält sich nicht wie ein Bot und unterscheidet sich daher nicht vom manuellen Einstellen.', 'تعمل الإضافة على حاسوبك الخاص وبحسابك الخاص؛ فهي تملأ النموذج وتُرفق الصور. أنت من يضغط دائمًا على «نشر» وتحلّ أي اختبار تحقق (كابتشا) بنفسك، وإذا طُلب رمز SMS فسيتم طلبه عبر تيليغرام. ولأنها لا تتصرف كروبوت، فلا فرق بينها وبين النشر اليدوي.'],
    'How do prices and quotas work?' => ['Wie funktionieren Preise und Kontingente?', 'كيف تعمل الأسعار والحصص؟'],
    'Packages are by duration and number of listings (e.g. 100 a month, 30 a week, single listing). A listing counts once even if it goes to 101evler, hangiev and social media. See your remaining quota and end date under My panel → “My package”; you get a reminder 3 days before it ends.' => ['Die Pakete richten sich nach Laufzeit und Anzahl der Inserate (z. B. 100 pro Monat, 30 pro Woche, Einzelinserat). Ein Inserat zählt nur einmal, auch wenn es zu 101evler, hangiev und Social Media geht. Ihr Restkontingent und das Enddatum sehen Sie unter Mein Panel → „Mein Paket“; 3 Tage vor Ablauf erhalten Sie eine Erinnerung.', ''],
    'What do I need for Facebook and Instagram posting?' => ['Was benötige ich für Beiträge auf Facebook und Instagram?', 'ما الذي أحتاجه للنشر على فيسبوك وإنستغرام؟'],
    'You need a Facebook Page and an Instagram Business or Creator account linked to it. You give our team access to your Page; you never share your password and can remove access at any time. We set up the connection. We do not post to Facebook groups automatically: Meta does not allow it and it can get accounts closed.' => ['Sie benötigen eine Facebook-Seite und ein damit verknüpftes Instagram-Business- oder Creator-Konto. Sie geben unserem Team Zugriff auf Ihre Seite; Ihr Passwort teilen Sie nie, und den Zugriff können Sie jederzeit entziehen. Die Verbindung richten wir für Sie ein. In Facebook-Gruppen posten wir nicht automatisch: Meta erlaubt dies nicht, und es kann zur Sperrung von Konten führen.', 'تحتاج إلى صفحة على فيسبوك وحساب إنستغرام تجاري (Business) أو حساب منشئ محتوى (Creator) مرتبط بها. تمنح فريقنا صلاحية الوصول إلى صفحتك دون مشاركة كلمة المرور، ويمكنك إلغاء هذه الصلاحية في أي وقت. نحن نتولى إعداد الربط. لا ننشر تلقائياً في مجموعات فيسبوك: فشركة Meta لا تسمح بذلك وقد يؤدي إلى إغلاق الحسابات.'],
    'How do I buy a package and pay?' => ['Wie kaufe und bezahle ich ein Paket?', 'كيف أشتري الباقة وكيف أدفع؟'],
    'Contact us with the “Message us to buy” button under My panel → “My package”. Your package is activated the same day after payment and confirmed by email.' => ['Kontaktieren Sie uns über die Schaltfläche „Zum Kauf schreiben“ unter Mein Bereich → „Mein Paket“. Nach der Zahlung wird Ihr Paket noch am selben Tag aktiviert und per E-Mail bestätigt.', 'تواصل معنا عبر زر «راسلنا للشراء» ضمن لوحتي ← «باقتي». بعد الدفع يتم تفعيل باقتك في اليوم نفسه ويصلك تأكيد عبر البريد الإلكتروني.'],
];
